var i=[{title:`Пасивна та активна амплітуда`,text:`Ви можете змогти перемістити руку над голову з допомогою, але мати труднощі з тим, щоб підняти її туди самостійно. Це вказує на достатню гнучкість без такої самої сили чи координації в цій амплітуді. Інші люди мають справді обмежений комфортний діапазон і можуть виграти від поступової розтяжки чи іншої варіації вправи.`},{title:`Перевіряйте рухи, які ви використовуєте`,text:`Контрольований підйом рук над голову, комфортний присід із вагою тіла чи нахил із відведенням тазу можуть показати, чи рух із вашого тренування відчувається обмеженим. Порівнюйте сторони, але не змушуйте їх збігатися. Мета: помітити практичну межу. Це не діагностує причину скутості, болю в суглобах чи медичного стану.`},{title:`Тренуйте контроль у доступній амплітуді`,text:`Динамічні кола руками, контрольовані випади, обертання грудного відділу та повільні рухи стегон дають змогу практикувати амплітуди під активним контролем. Силові вправи, виконані в комфортній амплітуді та прогресовані з часом, також можуть покращувати рухливість. Статична розтяжка покращує гнучкість, але сама по собі не завжди розвиває контроль.`},{title:`Немає єдиної ідеальної амплітуди`,text:`Пропорції тіла, будова суглобів, історія травм і навичка: усе це впливає на те, які рухи відчуваються комфортними. Вам не потрібні максимально глибокий присід чи екстремальна гнучкість плечей, щоб добре тренуватися. Оберіть амплітуду, де ваша техніка лишається стабільною та безболісною, і поступово будуйте від неї.`},{title:`Як це працює в TrainUp`,text:`Якщо певна ділянка тіла обмежує вашу амплітуду, додайте її як обмеження в Профілі з нотаткою. Тоді план добирає вправи, що відповідають вашим обмеженням, рівню та координації. Кожна сторінка вправи у розділі Вправи має кроки та нотатки про техніку. Запитайте лікаря чи фізіотерапевта про обмеження, що не минає, біль без пояснення чи симптоми, що впливають на повсякденне життя.`}];var n=[{label:`ACE 2026: рухливість і гнучкість`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: практичні поради щодо розтяжки`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:n};export{r as default,i as sections,n as sources};